// generar_281_quitar_resumen_redundante.js
// CHIQUI Entre Señales — Quitar el "Resumen del período" (4 números)
//
// Con la voz de Chiqui contando el mes en palabras ("se mantuvo
// estable, energía normal en el 92% de los días, 2 días con
// síntomas"), los 4 cuadritos de conteo del "Resumen del período"
// (Total · Verdes · Leve · Síntoma) quedaron repitiendo lo mismo en
// frío. Tener el dato dos veces alargaba la pantalla sin aportar, y
// los números sueltos son justo lo menos alineado con el espíritu de
// la app (Chiqui observa y te cuenta, no muestra un tablero).
//
// Se elimina ese bloque. Se CONSERVAN los otros dos porque cada uno
// responde una pregunta distinta:
//   · "Últimos 7 días" (barras por día) → la FORMA reciente: si los
//     días malos fueron seguidos o dispersos, si mejora o empeora.
//   · "Normalidad por categoría" → en QUÉ aspecto hubo cambios
//     (apetito, energía, digestión...).
//
// Jerarquía resultante, sin repetición:
//   Chiqui → el mes en palabras · 7 días → la forma reciente ·
//   Normalidad por categoría → en qué área.
//
// No hay SQL. Solo reescribe app/analisis/page.tsx.
//
// Uso:
//   node generar_281_quitar_resumen_redundante.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/analisis/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
